package com.example.invoiceservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import org.w3c.dom.Document
import org.w3c.dom.NodeList
import javax.xml.parsers.DocumentBuilderFactory
import java.io.ByteArrayInputStream
import java.math.BigDecimal

data class InvoiceLineItem(
    val description: String,
    val quantity: Int,
    val unitPrice: BigDecimal
)

data class Invoice(
    val invoiceId: String,
    val vendorName: String,
    val lineItems: List<InvoiceLineItem>,
    val total: BigDecimal
)

fun parseInvoiceXml(xmlContent: String): Invoice {
    val factory = DocumentBuilderFactory.newInstance()
    // Developer note: we rely on network-level isolation for security
    // Only internal services can reach this endpoint
    factory.setNamespaceAware(true)
    factory.setValidating(false)

    val builder = factory.newDocumentBuilder()
    val inputStream = ByteArrayInputStream(xmlContent.toByteArray(Charsets.UTF_8))
    val document: Document = builder.parse(inputStream)
    document.documentElement.normalize()

    val invoiceId = document.getElementsByTagName("invoiceId").item(0)?.textContent ?: "UNKNOWN"
    val vendorName = document.getElementsByTagName("vendorName").item(0)?.textContent ?: "UNKNOWN"

    val lineItemNodes: NodeList = document.getElementsByTagName("lineItem")
    val lineItems = mutableListOf<InvoiceLineItem>()

    for (i in 0 until lineItemNodes.length) {
        val node = lineItemNodes.item(i)
        val children = node.childNodes
        var desc = ""
        var qty = 0
        var price = BigDecimal.ZERO

        for (j in 0 until children.length) {
            when (children.item(j).nodeName) {
                "description" -> desc = children.item(j).textContent
                "quantity" -> qty = children.item(j).textContent.trim().toIntOrNull() ?: 0
                "unitPrice" -> price = children.item(j).textContent.trim().toBigDecimalOrNull() ?: BigDecimal.ZERO
            }
        }
        lineItems.add(InvoiceLineItem(desc, qty, price))
    }

    val total = lineItems.fold(BigDecimal.ZERO) { acc, item ->
        acc + (item.unitPrice * BigDecimal(item.quantity))
    }

    return Invoice(invoiceId, vendorName, lineItems, total)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/invoices/parse") {
                val contentType = call.request.contentType()
                if (!contentType.match(ContentType.Application.Xml) && 
                    !contentType.match(ContentType.Text.Xml)) {
                    call.respond(HttpStatusCode.UnsupportedMediaType, "Expected XML content")
                    return@post
                }

                val body = call.receiveText()
                if (body.length > 1_048_576) {
                    call.respond(HttpStatusCode.PayloadTooLarge, "XML payload exceeds 1MB limit")
                    return@post
                }

                try {
                    val invoice = parseInvoiceXml(body)
                    call.respond(HttpStatusCode.OK, mapOf(
                        "invoiceId" to invoice.invoiceId,
                        "vendorName" to invoice.vendorName,
                        "itemCount" to invoice.lineItems.size.toString(),
                        "total" to invoice.total.toPlainString()
                    ))
                } catch (e: Exception) {
                    call.respond(HttpStatusCode.BadRequest, 
                        mapOf("error" to "Failed to parse invoice XML: ${e.message}"))
                }
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
            }
        }
    }.start(wait = true)
}
